module digit_product_solver (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] B,\n    input wire [7:0] N,\n    output reg [31:0] X,\n    output reg valid,\n    output reg done\n);\n\n    // FSM States\n    localparam [3:0] IDLE        = 4'd0;\n    localparam [3:0] SETUP       = 4'd1;\n    localparam [3:0] FACTOR_LOOP = 4'd2;\n    localparam [3:0] CHECK_N     = 4'd3;\n    localparam [3:0] SORT_SETUP  = 4'd4;\n    localparam [3:0] SORT_LOOP   = 4'd5;\n    localparam [3:0] BUILD_X     = 4'd6;\n    localparam [3:0] DONE_STATE  = 4'd7;\n    localparam [3:0] IMPOSSIBLE  = 4'd8;\n\n    reg [3:0] state, next_state;\n    reg [7:0] temp_N;\n    reg [3:0] d;\n    reg [3:0] digits [0:7];  // Up to 8 digits\n    reg [2:0] digit_count;\n    reg [31:0] X_reg;\n    reg [2:0] sort_i, sort_j;\n    reg [2:0] build_idx;\n    reg swap_flag;\n    reg [7:0] cycle_count;\n    integer i;  // For-loops\n\n    // Division remainder\n    wire [7:0] remainder = temp_N % d;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            X <= 32'd0;\n            valid <= 1'b0;\n            done <= 1'b0;\n            temp_N <= 8'd0;\n            d <= 4'd0;\n            digit_count <= 3'd0;\n            X_reg <= 32'd0;\n            sort_i <= 3'd0;\n            sort_j <= 3'd0;\n            build_idx <= 3'd0;\n            swap_flag <= 1'b0;\n            cycle_count <= 8'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                digits[i] <= 4'd0;\n            end\n        end else begin\n            cycle_count <= (state != IDLE) ? cycle_count + 8'd1 : 8'd0;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    valid <= 1'b0;\n                    if (start) begin\n                        state <= SETUP;\n                        digit_count <= 3'd0;\n                        temp_N <= N;\n                    end\n                end\n\n                SETUP: begin\n                    if (N == 8'd1) begin\n                        digits[0] <= 4'd1;\n                        digit_count <= 3'd1;\n                        state <= BUILD_X;\n                    end else begin\n                        d <= B - 4'd1;\n                        digit_count <= 3'd0;\n                        state <= FACTOR_LOOP;\n                    end\n                end\n\n                FACTOR_LOOP: begin\n                    if (cycle_count >= 8'd100) state <= IMPOSSIBLE;\n                    else if (temp_N == 8'd1) state <= SORT_SETUP;\n                    else if (d < 4'd2) state <= CHECK_N;\n                    else if (remainder == 8'd0) begin\n                        digits[digit_count] <= d;\n                        digit_count <= digit_count + 3'd1;\n                        temp_N <= temp_N / d;\n                    end else begin\n                        d <= d - 4'd1;\n                    end\n                end\n\n                CHECK_N: begin\n                    if (temp_N == 8'd1) state <= SORT_SETUP;\n                    else state <= IMPOSSIBLE;\n                end\n\n                SORT_SETUP: begin\n                    sort_i <= 3'd0;\n                    sort_j <= 3'd0;\n                    swap_flag <= 1'b0;\n                    state <= SORT_LOOP;\n                end\n\n                SORT_LOOP: begin\n                    if (digit_count <= 3'd1) begin\n                        state <= BUILD_X;\n                    end else if (sort_i > digit_count - 3'd2) begin\n                        if (swap_flag) begin\n                            sort_i <= 3'd0;\n                            sort_j <= 3'd0;\n                            swap_flag <= 1'b0;\n                        end else begin\n                            state <= BUILD_X;\n                        end\n                    end else begin\n                        if (digits[sort_j] > digits[sort_j + 3'd1]) begin\n                            digits[sort_j] <= digits[sort_j + 3'd1];\n                            digits[sort_j + 3'd1] <= digits[sort_j];\n                            swap_flag <= 1'b1;\n                        end\n                        sort_j <= sort_j + 3'd1;\n                        if (sort_j >= digit_count - sort_i - 3'd2) begin\n                            sort_i <= sort_i + 3'd1;\n                            sort_j <= 3'd0;\n                        end\n                    end\n                end\n\n                BUILD_X: begin\n                    if (build_idx >= digit_count) begin\n                        X <= X_reg;\n                        valid <= 1'b1;\n                        state <= DONE_STATE;\n                    end else begin\n                        X_reg <= (X_reg * B) + digits[build_idx];\n                        build_idx <= build_idx + 3'd1;\n                    end\n                end\n\n                IMPOSSIBLE: begin\n                    valid <= 1'b0;\n                    X <= 32'd0;\n                    state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule